  { id: 2190, unit: 44, word: "hostel", phonetic: "[ `hɑstḷ ]", pos: "n.", trans: "青年旅館", collocation: "youth hostel (青年旅館)", synonym: "inn, lodge", enEx: "Backpackers stayed at budget youth <mark>hostel</mark> near train station.", chEx: "背包客住在車站附近的平價青年旅館。" },
  { id: 2191, unit: 44, word: "hostess", phonetic: "[ `hostɪs ]", pos: "n.", trans: "女主人；女主持人", collocation: "gracious hostess (親切的女主人)", synonym: "female host", enEx: "Gracious <mark>hostess</mark> served hot tea and cookies to guests.", chEx: "親切的女主人為客人端上了熱茶和餅乾。" },
  { id: 2192, unit: 44, word: "hostile", phonetic: "[ `hɑstḷ ]", pos: "a.", trans: "敵對的；不友善的", collocation: "hostile environment (敵對/惡劣的環境)", synonym: "unfriendly, aggressive", enEx: "Soldiers navigated through dangerous <mark>hostile</mark> territory carefully.", chEx: "士兵們小心翼翼地穿過危險的敵對領地。" },
  { id: 2193, unit: 44, word: "hostility", phonetic: "[ hɑs`tɪlətɪ ]", pos: "n.", trans: "敵意；對立", collocation: "open hostility (公開的敵意)", synonym: "enmity, antagonism", enEx: "Diplomats worked tirelessly to end ongoing military <mark>hostility</mark>.", chEx: "外交官們不懈努力以結束持續的軍事敵意。" },
  { id: 2194, unit: 44, word: "hot", phonetic: "[ hɑt ]", pos: "a.", trans: "炎熱的；辣的；熱門的", collocation: "hot weather (炎熱的天氣)", synonym: "scalding, spicy", enEx: "Enjoying cold ice cream feels great on hot summer afternoon.", chEx: "在炎熱的夏天午後享用冰涼的冰淇淋感覺非常棒。" },
  { id: 2195, unit: 44, word: "hotel", phonetic: "[ ho`tɛl ]", pos: "n.", trans: "飯店；旅館", collocation: "luxury hotel (奢華飯店)", synonym: "inn, resort", enEx: "Tourists booked oceanfront luxury <mark>hotel</mark> room for vacation.", chEx: "遊客們預訂了臨海奢華飯店客房度過假期。" },
  { id: 2196, unit: 44, word: "hour", phonetic: "[ aʊr ]", pos: "n.", trans: "小時", collocation: "peak hours (尖峰時段)", synonym: "sixty minutes", enEx: "Flight duration takes about three <mark>hour</mark>s from Taipei to Tokyo.", chEx: "從台北到東京的飛行時間大約需要三個小時。" },
  { id: 2197, unit: 44, word: "house", phonetic: "[ haʊs ]", pos: "n./v.", trans: "房屋；容納", collocation: "build a house (蓋房子)", synonym: "home, building", enEx: "Family built a cozy brick <mark>house</mark> with garden.", chEx: "這家人蓋了一棟帶花園的舒適磚房。" },
  { id: 2198, unit: 44, word: "household", phonetic: "[ `haʊsˌhold ]", pos: "n./a.", trans: "家庭；戶；家用的", collocation: "household chores (家務雜事)", synonym: "family, domestic", enEx: "Smart home appliances simplify routine <mark>household</mark> chores.", chEx: "智慧家電簡化了日常家務雜事。" },
  { id: 2199, unit: 44, word: "housewife", phonetic: "[ `haʊsˌwaɪf ]", pos: "n.", trans: "家庭主婦", collocation: "busy housewife (忙碌的家庭主婦)", synonym: "homemaker", enEx: "Busy <mark>housewife</mark> managed family budget and daily grocery cooking.", chEx: "忙碌的家庭主婦管理著家庭預算與日常買菜做飯。" },
  { id: 2200, unit: 44, word: "housework", phonetic: "[ `haʊsˌwɝk ]", pos: "n.", trans: "家事；家務", collocation: "do housework (做家事)", synonym: "chores, cleaning", enEx: "Family members share responsibility of doing weekend <mark>housework</mark>.", chEx: "家庭成員分擔做週末家事的責任。" }

