  { id: 2685, unit: 54, word: "letter", phonetic: "[ `lɛtɚ ]", pos: "n.", trans: "信件；字母", collocation: "cover letter (求職信/求職說明信)", synonym: "mail, note, character", enEx: "Applicant attached a cover <mark>letter</mark> with resume submission.", chEx: "申請人在提交履歷時附上了一封求職信。" },
  { id: 2686, unit: 54, word: "level", phonetic: "[ `lɛvḷ ]", pos: "n./a./v.", trans: "水平；等級；平坦的", collocation: "high level (高層次/高水準)", synonym: "stage, grade, flat", enEx: "Students reached an advanced proficiency <mark>level</mark> in English.", chEx: "學生的英文達到的高級熟練水平。" },
  { id: 2687, unit: 54, word: "leverage", phonetic: "[ `lɛvərɪdʒ ]", pos: "n./v.", trans: "槓桿作用；利用", collocation: "leverage resources (利用資源)", synonym: "advantage, utilize", enEx: "Company can <mark>leverage</mark> new tech to reduce costs.", chEx: "公司可以利用新科技來降低成本。" },
  { id: 2688, unit: 54, word: "liable", phonetic: "[ `laɪəbḷ ]", pos: "a.", trans: "有責任的；易於...的", collocation: "be liable for (對...負有責任)", synonym: "responsible, prone", enEx: "Driver is legally <mark>liable</mark> for property damage caused.", chEx: "駕駛人在法律上對造成的財產損失負有責任。" },
  { id: 2689, unit: 54, word: "liability", phonetic: "[ ˌlaɪə`bɪlətɪ ]", pos: "n.", trans: "責任；債務；不利因素", collocation: "financial liability (財務負債/責任)", synonym: "obligation, debt", enEx: "Company carries limited <mark>liability</mark> protection for shareholders.", chEx: "公司為股東承擔有限責任保護。" },
  { id: 2690, unit: 54, word: "liar", phonetic: "[ `laɪɚ ]", pos: "n.", trans: "說謊者", collocation: "compulsive liar (習慣性說謊者)", synonym: "deceiver", enEx: "Nobody trusted him because he was a known <mark>liar</mark>.", chEx: "沒有人信任他，因為他是一個眾所周知的說謊者。" },
  { id: 2691, unit: 54, word: "liberal", phonetic: "[ `lɪbərəl ]", pos: "a./n.", trans: "自由的；慷慨的；自由主義者", collocation: "liberal arts (人文學科/博雅教育)", synonym: "open-minded, generous", enEx: "University provides a comprehensive <mark>liberal</mark> arts education program.", chEx: "該大學提供全面的博雅教育課程。" },
  { id: 2692, unit: 54, word: "liberate", phonetic: "[ `lɪbəˌret ]", pos: "v.", trans: "解放；釋放", collocation: "liberate country (解放國家)", synonym: "free, release", enEx: "Troops fought bravely to <mark>liberate</mark> occupied city region.", chEx: "部隊英勇作戰以解放受佔領的城市區域。" },
  { id: 2693, unit: 54, word: "liberation", phonetic: "[ ˌlɪbə`reʃən ]", pos: "n.", trans: "解放", collocation: "national liberation (國家解放)", synonym: "freedom, release", enEx: "People celebrated the anniversary of national <mark>liberation</mark> day.", chEx: "人民慶祝國家解放日的周年紀念。" },
  { id: 2694, unit: 54, word: "liberty", phonetic: "[ `lɪbɚtɪ ]", pos: "n.", trans: "自由", collocation: "individual liberty (個人自由)", synonym: "freedom, independence", enEx: "Statue of Liberty represents hope and individual freedom.", chEx: "自由女神像象徵著希望與個人自由。" },
  { id: 2695, unit: 54, word: "librarian", phonetic: "[ laɪ`brɛrɪən ]", pos: "n.", trans: "圖書館員", collocation: "head librarian (圖書館館長/首席圖書館員)", synonym: "library keeper", enEx: "Friendly <mark>librarian</mark> helped student locate research materials.", chEx: "親切的圖書館員幫助學生找到了研究資料。" },
  { id: 2696, unit: 54, word: "library", phonetic: "[ `laɪˌbrɛrɪ ]", pos: "n.", trans: "圖書館", collocation: "public library (公共圖書館)", synonym: "book collection", enEx: "Students study quietly inside public <mark>library</mark> reading room.", chEx: "學生們在公共圖書館閱覽室內安靜地學習。" },
  { id: 2697, unit: 54, word: "license", phonetic: "[ `laɪsəns ]", pos: "n./v.", trans: "執照；許可", collocation: "driver's license (駕照)", synonym: "permit, legal pass", enEx: "He passed driving test and received driver's <mark>license</mark>.", chEx: "他通過了駕駛考試並拿到了駕駛執照。" },
  { id: 2698, unit: 54, word: "lick", phonetic: "[ lɪk ]", pos: "v./n.", trans: "舔", collocation: "lick ice cream (舔冰淇淋)", synonym: "lap, taste", enEx: "Dog began to <mark>lick</mark> owner's hand in affection.", chEx: "狗開始親暱地舔主人的手。" },
  { id: 2699, unit: 54, word: "lid", phonetic: "[ lɪd ]", pos: "n.", trans: "蓋子；眼瞼", collocation: "tight lid (緊密的蓋子)", synonym: "cover, cap", enEx: "Close coffee cup <mark>lid</mark> tightly to prevent liquid spilling.", chEx: "蓋緊咖啡杯蓋以防止液體溢出。" },
  { id: 2700, unit: 54, word: "lie", phonetic: "[ laɪ ]", pos: "v./n.", trans: "躺；位於；說謊", collocation: "tell a lie (說謊)", synonym: "recline, fib, falsehood", enEx: "Patient was asked to <mark>lie</mark> down on examination bed.", chEx: "病人被要求躺在檢查床上。" }

